// @FIGURE_CODE_BEGIN
// ── Element spec ───────────────────────────────────────────────────────────
// axis shaft          → CylinderGeometry(r=0.02)              black #1A1A1A
// axis arrowhead      → ConeGeometry(0.085, 0.22)             black
// hidden axis part    → Line + LineDashedMaterial             black
// origin dot          → SphereGeometry(0.09)                  black (depthTest off)
// a) teal "point"     → BoxGeometry(0.10, 0.90, 0.02)         teal #8CCFC9
// a) half-space shade → PlaneGeometry(1,1) scaled             teal tint
// b) hyperplane bars  → BoxGeometry(4.6, 0.13, 0.02)          teal / terracotta
// b) half-space shade → PlaneGeometry(5.0, 2.2)               tinted, 0.10-0.18
// c) gray card        → PlaneGeometry(4.4, 4.0)               gray #C7CBCD 0.70
// c) neuron planes    → PlaneGeometry(4.4/4.6 square)         teal 0.75 / orange 0.85
// c) plane outline    → EdgesGeometry + LineBasicMaterial     active only
// c) half-space slab  → BoxGeometry(w,h,1.3)                  tinted
// input point x       → SphereGeometry(0.12) + invisible hit sphere(0.35)
// drop lines          → Line + LineDashedMaterial             black thin

const COL = { black: 0x1A1A1A, teal: 0x8CCFC9, orange: 0xD2704E, gray: 0xC7CBCD };
const TEAL_D = 0x3FA79C, OR_D = 0xA8492A;
const V = (x, y, z) => new THREE.Vector3(x, y, z);
const HIDE = V(0, 1e4, 0);

/* ── builders ─────────────────────────────────────────────────────────── */
function shaft(a, b, color, radius) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  dir.normalize();
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, len, 10),
    new THREE.MeshBasicMaterial({ color })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
  return m;
}
function dashedSeg(a, b, color, dash = 0.13, gap = 0.09) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  const l = new THREE.Line(g, new THREE.LineDashedMaterial({ color, dashSize: dash, gapSize: gap }));
  l.computeLineDistances();
  return l;
}
function arrow(a, b, opt = {}) {
  const color = opt.color ?? COL.black;
  const g = new THREE.Group();
  const dir = b.clone().sub(a).normalize();
  const headLen = opt.head === false ? 0 : 0.22;
  const end = b.clone().sub(dir.clone().multiplyScalar(headLen));
  if (opt.dashed) g.add(dashedSeg(a, end, color));
  else g.add(shaft(a, end, color, opt.radius ?? 0.02));
  if (opt.head !== false) {
    const c = new THREE.Mesh(new THREE.ConeGeometry(0.085, headLen, 16),
      new THREE.MeshBasicMaterial({ color }));
    c.position.copy(b).sub(dir.clone().multiplyScalar(headLen / 2));
    c.quaternion.setFromUnitVectors(V(0, 1, 0), dir);
    g.add(c);
  }
  return g;
}
function dot(p, r = 0.09) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 20, 14),
    new THREE.MeshBasicMaterial({ color: COL.black, depthTest: false }));
  m.position.copy(p);
  m.renderOrder = 20;
  return m;
}
function planeMesh(w, h, color, opacity, order) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({
