/* ── update ───────────────────────────────────────────────────────────── */
function clampPoint() {
  const p = state.point;
  if (state.dim < 3) p.z = 0;
  if (state.dim < 2) p.y = 0;
  if (p.length() > 2.6) p.setLength(2.6);
}

function updateA() {
  const n = state.neurons[0];
  const w1 = n.w[0];
  if (Math.abs(w1) < 1e-4) { aBar.visible = false; aShade.visible = false; return; }
  const x0 = Math.max(-2.8, Math.min(2.8, -n.b / w1));
  aBar.visible = true; aBar.position.set(x0, 0, 0.02);
  const end = w1 > 0 ? 3 : -3;
  aShade.visible = true;
  aShade.scale.set(Math.abs(end - x0) || 0.001, 0.9, 1);
  aShade.position.set((x0 + end) / 2, 0, -0.01);
}

function updateB() {
  for (let i = 0; i < 2; i++) {
    const { w, b, len } = neuronVec(i);
    const g = barGroups[i];
    if (len < 1e-4) { g.visible = false; continue; }
    g.visible = true;
    const nx = w.x / len, ny = w.y / len;
    const m = new THREE.Matrix4().makeBasis(V(ny, -nx, 0), V(nx, ny, 0), V(0, 0, 1));
    g.quaternion.setFromRotationMatrix(m);
    g.position.set(-b * nx / len, -b * ny / len, 0);
    const act = state.active === i;
    g.userData.bar.material.opacity = act ? 1.0 : 0.55;
    g.userData.sh.material.opacity = act ? 0.18 : 0.10;
  }
}

function updateC() {
  for (let i = 0; i < 2; i++) {
    const { w, b, len } = neuronVec(i);
    const g = planeGroups[i];
    if (len < 1e-4) { g.visible = false; continue; }
    g.visible = true;
    const nh = w.clone().divideScalar(len);
    g.quaternion.setFromUnitVectors(V(0, 0, 1), nh);
    g.position.copy(nh).multiplyScalar(-b / len);
    const act = state.active === i;
    g.userData.pm.material.opacity = act ? (i === 0 ? 0.78 : 0.88) : 0.38;
    g.userData.outline.visible = act;
    g.userData.slab.material.opacity = act ? 0.16 : 0.07;
  }
}

function updateReadout() {
  const p = state.point;
  const z1 = preAct(0, p), z2 = preAct(1, p);
  const s = v => v >= 0 ? '+' : '−';
  let html = `x = (${p.x.toFixed(2)}` +
    (state.dim >= 2 ? `, ${p.y.toFixed(2)}` : '') +
    (state.dim >= 3 ? `, ${p.z.toFixed(2)}` : '') + ')<br>';
  html += `<span style="color:#2f867d">z₁</span> = ${z1.toFixed(2)} → sign ${s(z1)}`;
  if (state.dim >= 2) html += `<br><span style="color:#b0532f">z₂</span> = ${z2.toFixed(2)} → sign ${s(z2)}`;
  const cls = state.dim >= 2
    ? ((z1 > 0 ? 1 : 0) * 2 + (z2 > 0 ? 1 : 0)) + 1
    : (z1 > 0 ? 2 : 1);
  html += `<br>output class = <b>${cls}</b>`;
  document.getElementById('readout').innerHTML = html;
}

function updateAll() {
  clampPoint();
