  const p = state.point;
  ptMesh.position.copy(p); ptHit.position.copy(p);
  labPoint.home.copy(p); labPoint.e.pos.copy(p);
  dropLines.forEach(l => l.visible = false);
  if (state.dim === 2) {
    setDrop(0, p, V(p.x, 0, 0));
    setDrop(1, p, V(0, p.y, 0));
  } else if (state.dim === 3) {
    setDrop(0, p, V(p.x, 0, p.z));
    setDrop(1, V(p.x, 0, p.z), V(p.x, 0, 0));
    setDrop(2, V(p.x, 0, p.z), V(0, 0, p.z));
