const _dragPlane = new THREE.Plane();
const _hitPt = new THREE.Vector3();
let dragging = false;
const dom = renderer.domElement;
function toNdc(e) {
  const r = dom.getBoundingClientRect();
  _nd.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _nd.y = -((e.clientY - r.top) / r.height) * 2 + 1;
