const STEPS = [
  { title: 'a) One dimension: a point', narration: "On a single number line the neuron's boundary w₁x₁ + β = 0 is just one point. Everything right of it is positive, everything left is negative.", state: { dim: 1, active: 0, w1: 1, w2: 0, w3: 0, b: 0 } },
  { title: 'Bias slides the point', narration: 'Increasing the bias moves the dividing point along x₁ without changing which side is positive — the shaded region slides with it.', state: { dim: 1, b: 0.9 } },
  { title: 'b) Two dimensions: a line', narration: "With two inputs each neuron's boundary is a line through the origin. The teal neuron uses only x₁, so its line is vertical; the orange neuron uses only x₂, so its line is horizontal.", state: { dim: 2, active: 0, w1: 1, w2: 0, w3: 0, b: 0 } },
  { title: 'Tilting the teal line', narration: 'Adding weight on x₂ rotates the teal boundary. The two neurons now carve the plane into four regions instead of the original quadrants.', state: { dim: 2, active: 0, w1: 1, w2: 0.8, b: 0 } },
  { title: 'c) Three dimensions: a plane', narration: 'In 3D the same equation describes a flat plane. Orbit to see the gray, teal and orange planes meeting at the origin, each the boundary of one neuron.', state: { dim: 3, active: 0, w1: 1, w2: 0, w3: 0, b: 0 } },
  { title: 'Tipping the plane and testing a point', narration: "Weight on x₃ tips the teal plane out of the screen. Drag the input point through space and watch each neuron's sign — and the combined output class — switch as it crosses a plane.", state: { dim: 3, active: 0, w1: 1, w2: 0.4, w3: 0.9, b: 0.3 } }
];
let stepIdx = -1;
let tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  const st = s.state;
  if (st.active !== undefined) setActive(st.active);
  if (st.dim !== undefined && st.dim !== state.dim) setDim(st.dim);
  const n = state.neurons[state.active];
  const to = {
    w: [st.w1 !== undefined ? st.w1 : n.w[0],
        st.w2 !== undefined ? st.w2 : n.w[1],
        st.w3 !== undefined ? st.w3 : n.w[2]],
    b: st.b !== undefined ? st.b : n.b
  };
  tween = { i: state.active, from: { w: n.w.slice(), b: n.b }, to, t0: performance.now(), dur: 550 };
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length} · ${s.title}`;
  document.getElementById('stepText').textContent = s.narration;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k * k * (3 - 2 * k);
    const n = state.neurons[tween.i];
    for (let j = 0; j < 3; j++) n.w[j] = tween.from.w[j] + (tween.to.w[j] - tween.from.w[j]) * e;
    n.b = tween.from.b + (tween.to.b - tween.from.b) * e;
    syncSliders();
    updateAll();
    if (k >= 1) tween = null;
  }
}
tick();

