}

/* ── labels ───────────────────────────────────────────────────────────── */
const MATH = s => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">x</span><sub style="font-family:Georgia,serif">${s}</sub>`;
const LS = { fontSize: '15px', color: '#111' };
const PS = { fontSize: '17px', color: '#111' };
addLabel('a)', V(PX.a - 2.1, 2.25, 0), PS);
addLabel(MATH(1), V(PX.a + 2.15, -0.35, 0), LS);
addLabel('b)', V(PX.b - 2.1, 2.25, 0), PS);
addLabel(MATH(1), V(PX.b + 2.15, -0.35, 0), LS);
addLabel(MATH(2), V(PX.b + 0.42, 2.05, 0), LS);
addLabel('c)', V(PX.c - 2.6, 2.25, 0), PS);
addLabel(MATH(1), V(PX.c + 2.25, -0.35, 0), LS);
addLabel(MATH(2), V(PX.c + 0.42, 2.05, 0), LS);
addLabel(MATH(3), V(PX.c, -0.12, 2.25), LS);
const HIDE = V(0, 1e4, 0);
const ptLabel = addLabel('<b>x</b>', V(0, 1e4, 0), { fontSize: '13px', color: '#111', offset: [13, -12] });

/* ── state ────────────────────────────────────────────────────────────── */
const DEF = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
const st = {
  active: 0,
  neurons: [{ w: [1, 0, 0], b: 0 }, { w: [0, 1, 0], b: 0 }, { w: [0, 0, 1], b: 0 }],
  px: [1.1, 0.8, 0.7],
  showHalf: false, showPoint: false
};
const clamp = (v, m) => Math.max(-m, Math.min(m, v));

/* ── per-panel updates ────────────────────────────────────────────────── */
function updateA(i) {
  const n = st.neurons[i], g = bA[i], w1 = n.w[0];
  if (Math.abs(w1) < 1e-5) { g.visible = false; return; }
  const x0 = -n.b / w1;
  if (Math.abs(x0) > 1.85) { g.visible = false; return; }
  g.visible = true; g.userData.tick.position.x = x0;
  const sh = g.userData.sh; sh.visible = st.showHalf;
  if (st.showHalf) {
    const end = w1 > 0 ? AX : -AX;
    sh.scale.x = Math.max(Math.abs(end - x0), 0.001);
    sh.position.x = (x0 + end) / 2;
  }
}
function updateB(i) {
  const n = st.neurons[i], g = bB[i];
  const w = V(n.w[0], n.w[1], 0), len = w.length();
  if (len < 1e-5) { g.visible = false; return; }
  const nh = w.clone().divideScalar(len), off = -n.b / len;
  if (Math.abs(off) > 1.9) { g.visible = false; return; }
  g.visible = true;
  const m = new THREE.Matrix4().makeBasis(V(-nh.y, nh.x, 0), nh, V(0, 0, 1));
  g.quaternion.setFromRotationMatrix(m);
  g.position.copy(nh).multiplyScalar(off);
  g.userData.sh.visible = st.showHalf;
}
function updateC(i) {
  const n = st.neurons[i], g = bC[i];
  const w = V(n.w[0], n.w[1], n.w[2]), len = w.length();
  if (len < 1e-5) { g.visible = false; return; }
  const nh = w.clone().divideScalar(len), off = -n.b / len;
  if (Math.abs(off) > 2.2) { g.visible = false; return; }
  g.visible = true;
  g.quaternion.setFromUnitVectors(V(0, 0, 1), nh);
  g.position.copy(nh).multiplyScalar(off);
  g.userData.outline.visible = (st.active === i);
  g.userData.slab.visible = st.showHalf;
}

/* ── point + readout ──────────────────────────────────────────────────── */
function updatePoint() {
  const p = st.px;
  ptMesh.a.visible = ptMesh.b.visible = ptMesh.c.visible = st.showPoint;
  ptHit.forEach(h => h.visible = st.showPoint);
  guides.forEach(l => l.visible = false);
  if (!st.showPoint) { ptLabel.pos.copy(HIDE); return; }
  ptMesh.a.position.set(p[0], 0, 0.05);
  ptMesh.b.position.set(p[0], p[1], 0.05);
  ptMesh.c.position.set(p[0], p[1], p[2]);
  ptHit[0].position.copy(ptMesh.a.position);
  ptHit[1].position.copy(ptMesh.b.position);
  ptHit[2].position.copy(ptMesh.c.position);
  ptLabel.pos.set(PX.c + p[0], p[1], p[2]);
  setGuide(0, V(p[0], p[1], 0.05), V(p[0], 0, 0.05));
  setGuide(1, V(p[0], p[1], p[2]), V(p[0], 0, p[2]));
  setGuide(2, V(p[0], 0, p[2]), V(p[0], 0, 0));
  setGuide(3, V(p[0], 0, p[2]), V(0, 0, p[2]));
}
function zOf(i, dim) {
  const n = st.neurons[i];
  let s = n.b;
  for (let j = 0; j < dim; j++) s += n.w[j] * st.px[j];
  return s;
}
const f2 = v => (v < 0 ? '−' : '+') + Math.abs(v).toFixed(2);
function updateReadout() {
  const i = st.active, n = st.neurons[i];
  let h = `<b>${NAMES[i]}</b><br>z = ${n.w[0].toFixed(2)}·x₁ ${f2(n.w[1])}·x₂ ${f2(n.w[2])}·x₃ ${f2(n.b)}<br>`;
  const aOK = bA[i].visible, bOK = bB[i].visible, cOK = bC[i].visible;
  h += `a) ${aOK ? 'point' : '— (w₁ = 0)'} · b) ${bOK ? 'line' : '—'} · c) ${cOK ? 'plane' : '—'}`;
  if (st.showPoint) {
    h += `<br>x = (${st.px[0].toFixed(2)}, ${st.px[1].toFixed(2)}, ${st.px[2].toFixed(2)})`;
    h += `<br>z in a) ${f2(zOf(i, 1))} · b) ${f2(zOf(i, 2))} · c) ${f2(zOf(i, 3))}`;
    h += `<br>neuron fires in c): <b>${zOf(i, 3) > 0 ? 'yes' : 'no'}</b>`;
  }
  document.getElementById('readout').innerHTML = h;
}
function updateAll() {
  for (let i = 0; i < 3; i++) { updateA(i); updateB(i); updateC(i); }
  updatePoint(); updateReadout();
}

/* ── camera: printed oblique (cabinet) projection ─────────────────────── */
const obState = () => (window.__figverify && window.__figverify.obliqueState) ? window.__figverify.obliqueState() : null;
let wantShear = 1, camTween = null, lastHidden = true;
function applyCamera() {
  camTween = null;
  const ob = obState(); if (ob) ob.shearTarget = 1;
  wantShear = 1;
  setCameraView({
    projection: 'oblique', obliqueAngleDeg: 35, depthScale: 0.55,
    target: [-0.4, 0, 0], heightFraction: 0.9
  });
}
function guardShear() {
  const ob = obState(); if (!ob) return;
  ob.shearTarget = wantShear;
  const b = document.getElementById('btnProjToggle');
  if (b) b.textContent = wantShear > 0.5 ? '3D view' : 'Figure view';
}
function orbitTo3D() {
  const tgt = V(PX.c, 0, 0);
  const az = THREE.MathUtils.degToRad(62), el = THREE.MathUtils.degToRad(24);
  const dir = V(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el));
  camTween = {
    p0: camera.position.clone(), p1: dir.multiplyScalar(14).add(tgt),
    t0: controls.target.clone(), t1: tgt, z0: camera.zoom, z1: 0.95,
    start: performance.now(), dur: 750
  };
  controls.dispatchEvent({ type: 'start' });   // tell the scaffold the pose is user-owned
}

/* ── UI wiring ────────────────────────────────────────────────────────── */
const sIds = ['sW1', 'sW2', 'sW3', 'sB'], vIds = ['vW1', 'vW2', 'vW3', 'vB'];
function syncSliders() {
  const n = st.neurons[st.active], vals = [n.w[0], n.w[1], n.w[2], n.b];
  sIds.forEach((id, k) => {
    document.getElementById(id).value = vals[k];
    document.getElementById(vIds[k]).textContent = vals[k].toFixed(2);
  });
}
function setActive(i) {
  st.active = i;
  document.querySelectorAll('#neuronGroup button').forEach(b =>
    b.classList.toggle('active', +b.dataset.neuron === i));
  syncSliders(); updateAll();
}
sIds.forEach((id, k) => document.getElementById(id).addEventListener('input', e => {
  tween = null;
  const v = parseFloat(e.target.value), n = st.neurons[st.active];
  if (k < 3) n.w[k] = v; else n.b = v;
  document.getElementById(vIds[k]).textContent = v.toFixed(2);
  updateAll();
}));
document.querySelectorAll('#neuronGroup button').forEach(b =>
  b.addEventListener('click', () => setActive(+b.dataset.neuron)));
document.getElementById('btnResetW').addEventListener('click', () => {
  tween = null;
  st.neurons.forEach((n, i) => { n.w = DEF[i].slice(); n.b = 0; });
  syncSliders(); updateAll();
});
const pIds = ['pX1', 'pX2', 'pX3'], pvIds = ['vP1', 'vP2', 'vP3'];
function syncPoint() {
  pIds.forEach((id, k) => {
    document.getElementById(id).value = st.px[k];
    document.getElementById(pvIds[k]).textContent = st.px[k].toFixed(2);
  });
}
pIds.forEach((id, k) => document.getElementById(id).addEventListener('input', e => {
  st.px[k] = parseFloat(e.target.value);
  document.getElementById(pvIds[k]).textContent = st.px[k].toFixed(2);
  updateAll();
}));
function setShowPoint(on) {
  st.showPoint = on;
  document.getElementById('chkPoint').checked = on;
  document.getElementById('pointCtl').style.display = on ? 'flex' : 'none';
  updateAll();
}
document.getElementById('chkPoint').addEventListener('change', e => setShowPoint(e.target.checked));
document.getElementById('chkHalf').addEventListener('change', e => { st.showHalf = e.target.checked; updateAll(); });
const btnReset = document.getElementById('btnReset');
btnReset.style.display = ''; btnReset.addEventListener('click', applyCamera);
document.getElementById('btnProjToggle').addEventListener('click', () => {
  const ob = obState(); if (!ob) return;
  wantShear = ob.shearTarget;
  if (wantShear < 0.5) orbitTo3D(); else applyCamera();
});

/* ── dragging the test point ──────────────────────────────────────────── */
const _ray = new THREE.Raycaster(), _nd = new THREE.Vector2();
const _pl = new THREE.Plane(), _hit = new THREE.Vector3();
let dragging = null;
const dom = renderer.domElement;
function ndc(e) {
  const r = dom.getBoundingClientRect();
  _nd.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
}
dom.addEventListener('pointerdown', e => {
  if (!st.showPoint) return;
  ndc(e); _ray.setFromCamera(_nd, camera);
  const hits = _ray.intersectObjects(ptHit, false);
  if (!hits.length) return;
  dragging = hits[0].object.userData.panel;
  controls.enabled = false;
  if (dragging === 'c') {
    const nrm = new THREE.Vector3(); camera.getWorldDirection(nrm);
    _pl.setFromNormalAndCoplanarPoint(nrm, hits[0].object.getWorldPosition(new THREE.Vector3()));
  } else {
    _pl.set(V(0, 0, 1), 0);
  }
  e.preventDefault();
});
dom.addEventListener('pointermove', e => {
  if (!dragging) return;
  guardShear();
  ndc(e); _ray.setFromCamera(_nd, camera);
  if (!_ray.ray.intersectPlane(_pl, _hit)) return;
  const lx = clamp(_hit.x - PX[dragging], 1.8);
  st.px[0] = lx;
  if (dragging !== 'a') st.px[1] = clamp(_hit.y, 1.8);
  syncPoint(); updateAll();
});
window.addEventListener('pointerup', () => { if (dragging) { dragging = null; controls.enabled = true; } });

/* ── guided demo ──────────────────────────────────────────────────────── */
let tween = null;
function tweenTo(i, w, b) {
  const n = st.neurons[i];
  tween = { i, from: { w: n.w.slice(), b: n.b }, to: { w: w.slice(), b }, t0: performance.now(), dur: 600 };
}
function resetNeurons() { st.neurons.forEach((n, i) => { n.w = DEF[i].slice(); n.b = 0; }); }
const STEPS = [
  {
    title: 'One neuron, three input spaces',
    text: 'The teal neuron computes z = x₁. Its boundary z = 0 is a POINT in a), a LINE in b) and a PLANE in c) — always one dimension below the input space. All three panels are the same neuron.',
    apply() { resetNeurons(); setShowPoint(false); setActive(0); tweenTo(0, [1, 0, 0], 0); }
  },
  {
    title: 'The bias slides the boundary',
    text: 'β shifts the boundary away from the origin along the weight direction. Watch the teal point, line and plane all move together by the same amount −β/|w|.',
    apply() { setActive(0); tweenTo(0, [1, 0, 0], 0.8); }
  },
  {
    title: 'The weights rotate it',
    text: 'Giving x₂ some weight rotates the boundary so it stays perpendicular to w. In a) only w₁ and β matter, so the point simply moves; in b) the line tilts; in c) the plane turns about the x₃ axis.',
    apply() { setActive(0); tweenTo(0, [1, 0.8, 0], 0); }
  },
  {
    title: 'The third input exists only in c)',
    text: 'Adding w₃ tips the teal plane out of the picture plane. Panels a) and b) cannot show it at all — a 1-D or 2-D input space has no x₃ direction for the hyperplane to lean into.',
    apply() { setActive(0); tweenTo(0, [1, 0.5, 0.9], 0.2); }
  },
  {
    title: 'A layer is several hyperplanes',
    text: 'The orange and gray neurons have their own weights. Together the neurons of a layer slice the input space into regions — two lines make four regions in b), three planes make eight in c).',
    apply() { resetNeurons(); setActive(1); tweenTo(1, [0, 1, 0], 0); }
  },
  {
    title: 'Which side is an input on?',
    text: 'The test input x appears in every panel, using as many coordinates as that panel has. The sign of z tells you which half-space it lies in — drag x, or use the x₁/x₂/x₃ sliders, and watch the sign flip as it crosses the boundary.',
    apply() { setShowPoint(true); setActive(0); tweenTo(0, [1, 0.5, 0.9], 0.2); }
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  s.apply(); syncSliders(); updateAll();
  document.getElementById('stepTitle').textContent = `${stepIdx + 1}/${STEPS.length} · ${s.title}`;
  document.getElementById('stepText').textContent = s.text;
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── frame loop: tweens, shear guard, hidden-line visibility ──────────── */
function tick() {
  requestAnimationFrame(tick);
  const ob = obState();
  if (ob) {
    if (dragging) guardShear(); else wantShear = ob.shearTarget;
    const show = ob.shearAmt > 0.5;
    if (show !== lastHidden) { hiddenLines.forEach(l => l.visible = show); lastHidden = show; }
  }
  if (camTween) {
    const k = Math.min(1, (performance.now() - camTween.start) / camTween.dur);
    const e = k * k * (3 - 2 * k);
    camera.position.lerpVectors(camTween.p0, camTween.p1, e);
    controls.target.lerpVectors(camTween.t0, camTween.t1, e);
    camera.zoom = camTween.z0 + (camTween.z1 - camTween.z0) * e;
    camera.updateProjectionMatrix();
    if (k >= 1) camTween = null;
  }
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k * k * (3 - 2 * k), n = st.neurons[tween.i];
    for (let j = 0; j < 3; j++) n.w[j] = tween.from.w[j] + (tween.to.w[j] - tween.from.w[j]) * e;
    n.b = tween.from.b + (tween.to.b - tween.from.b) * e;
    if (tween.i === st.active) syncSliders();
    updateAll();
    if (k >= 1) tween = null;
  }
}
tick();

/* ── init ─────────────────────────────────────────────────────────────── */
setActive(0);
syncSliders(); syncPoint(); updateAll();
applyCamera();
document.getElementById('stepTitle').textContent = 'Press "Next ▶" for the walkthrough';
document.getElementById('stepText').textContent = '';
// @FIGURE_CODE_END
